<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>테트리스</title>
<style>
  body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#111;color:#eee;font-family:-apple-system,"Malgun Gothic",sans-serif}
  #wrap{display:flex;gap:20px;align-items:flex-start}
  canvas{background:#000;border:2px solid #444;display:block}
  #side{width:150px}
  #side h1{margin:0 0 12px;font-size:22px}
