  ctx.clearRect(0, 0, board.width, board.height);
  ctx.strokeStyle = '#161616';
  for (let x = 1; x < COLS; x++) { ctx.beginPath(); ctx.moveTo(x * S, 0); ctx.lineTo(x * S, ROWS * S); ctx.stroke(); }
  for (let y = 1; y < ROWS; y++) { ctx.beginPath(); ctx.moveTo(0, y * S); ctx.lineTo(COLS * S, y * S); ctx.stroke(); }
  grid.forEach((row, y) => row.forEach((t, x) => { if (t) cell(ctx, x, y, COLORS[t], S); }));
  if (!over) {
    let gy = cur.y;
    while (!collide(cur.shape, cur.x, gy + 1)) gy++;
    cur.shape.forEach((row, r) => row.forEach((v, c) => {
      if (v) cell(ctx, cur.x + c, gy + r, COLORS[cur.t], S, 0.2);
    }));
    cur.shape.forEach((row, r) => row.forEach((v, c) => {
      if (v && cur.y + r >= 0) cell(ctx, cur.x + c, cur.y + r, COLORS[cur.t], S);
    }));
  }
  if (over || paused) {
    ctx.fillStyle = 'rgba(0,0,0,0.65)';
    ctx.fillRect(0, 0, board.width, board.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = 'bold 32px sans-serif';
    ctx.fillText(over ? '게임 오버' : '일시정지', board.width / 2, board.height / 2 - 10);
    ctx.font = '16px sans-serif';
    ctx.fillText(over ? 'Enter로 다시 시작' : 'P로 계속', board.width / 2, board.height / 2 + 24);
  }
}

function loop(t) {
  const dt = t - (lastTime || t);
  lastTime = t;
  if (!over && !paused) {
    acc += dt;
    const speed = Math.max(80, 800 - (level - 1) * 70);
    while (acc >= speed && !over) { acc -= speed; softDrop(); }
  }
  updateInfo();
  draw();
  requestAnimationFrame(loop);
}

document.addEventListener('keydown', e => {
  if (e.key === 'Enter') { reset(); return; }
  if (e.key === 'p' || e.key === 'P') { if (!over) paused = !paused; return; }
  if (over || paused) return;
  switch (e.key) {
    case 'ArrowLeft': move(-1); break;
    case 'ArrowRight': move(1); break;
    case 'ArrowDown': if (softDrop()) score += 1; acc = 0; break;
    case 'ArrowUp': case 'x': case 'X': rotate(true); break;
    case 'z': case 'Z': rotate(false); break;
    case ' ': hardDrop(); break;
    default: return;
  }
  e.preventDefault();
});

reset();
requestAnimationFrame(loop);
</script>
</body>
</html>
